/* CIE colorimetry workspace. Original UI; calculations run locally. */
(function(){'use strict';
const C=window.CIECore,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=id=>{const v=$(id).value;if(v.trim()==='')throw Error('Complete all required numerical inputs.');return Number(v);},fmt=(v,n=5)=>Number.isFinite(v)?v.toFixed(n):'—',signed=v=>(v>=0?'+':'')+fmt(v,6);
let current={...C.whites.D65},source='Coordinate input',spectral=null,parsed=null,saved=[],device=null,analysis;const backgrounds={};
const descriptions={D65:'D65 daylight · x = 0.31270, y = 0.32900',D50:'D50 daylight · x = 0.34570, y = 0.35850',D55:'D55 daylight reference',D75:'D75 daylight reference',A:'Illuminant A · incandescent reference',C:'Illuminant C · legacy daylight reference',E:'Equal-energy illuminant E · x = y = 1/3',custom:'Enter a physically valid achromatic reference in xy.'};
function status(s,error=false,id='color-status'){$(id).textContent=s;$(id).classList.toggle('is-error',error);}
function guard(fn,id='color-status'){return()=>{try{fn();}catch(e){status(e.message,true,id);}};}
function white(){return $('color-white').value==='custom'?C.validateXY({x:num('color-white-x'),y:num('color-white-y')}):C.whites[$('color-white').value];}
function mode(name){document.querySelectorAll('[data-color-mode]').forEach(b=>{const active=b.dataset.colorMode===name;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});for(const s of ['coordinates','spectrum','temperature'])$('color-'+s+'-panel').hidden=s!==name;}
function syncCoordinates(){const kind=$('color-coordinate-kind').value;const p=kind==='xy'?current:kind==='uv'?C.uv76(current):C.xyXYZ(current);$('color-a-label').textContent=kind==='xy'?'x':kind==='uv'?'u′':'X';$('color-b-label').textContent=kind==='xy'?'y':kind==='uv'?'v′':'Y';$('color-c-wrap').hidden=kind!=='xyz';$('color-a').value=fmt(kind==='xyz'?p.X:p.x,8);$('color-b').value=fmt(kind==='xyz'?p.Y:p.y,8);if(kind==='xyz')$('color-c').value=fmt(p.Z,8);}
function setColor(p,name,sp=null){C.validateXY(p);current={x:p.x,y:p.y};source=name;spectral=sp;syncCoordinates();render();document.dispatchEvent(new CustomEvent('cie-source-changed',{detail:{source,xy:current,spectrum:sp?{rows:parsed.rows,xcol:num('color-wave-column'),ycol:num('color-power-column'),unit:$('color-wave-unit').value,basis:$('color-basis').value,clamp:$('color-clamp').checked}:null}}));status(name+' calculated.');}
function metric(label,value,note){return '<div class="color-metric"><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong><p>'+esc(note)+'</p></div>';}
function render(){analysis=C.analyze(current,white());const a=analysis,k=a.cct,p=a.purity;
 $('color-metrics').innerHTML=metric('CIE 1931 x, y',fmt(current.x)+', '+fmt(current.y),'Official CIE 1931 standard observer')+metric('CIE 1976 u′, v′',fmt(a.uv.x)+', '+fmt(a.uv.y),'Uniform chromaticity scale')+metric('Correlated color temperature',k.valid?Math.round(k.temperature).toLocaleString()+' K':'Not applicable',k.valid?'Closest Planckian radiator in CIE 1960 uv':k.bounded?'Nearest radiator reaches the search limit':'Outside the near-white CCT domain')+metric('Duv',signed(k.duv),'Signed distance in CIE 1960 uv'+(k.valid?'':' · diagnostic only'))+metric('Excitation purity',fmt(p.purity,2)+'%','Relative to '+($('color-white').value==='custom'?'custom white':$('color-white').value))+metric(p.kind,p.wavelength===null?'Undefined':fmt(p.wavelength,1)+' nm',p.wavelength===null?'At the reference white':p.kind==='Complementary wavelength'?'Opposite spectral ray for purple-side colors':'Spectral boundary along white → sample');
 $('color-more-results').innerHTML=[['Relative XYZ · Y = 100',[a.xyz.X,a.xyz.Y,a.xyz.Z].map(v=>fmt(v,3)).join(', ')],['Chromaticity z',fmt(1-current.x-current.y)],['CIE 1960 u, v',fmt(a.u60.x)+', '+fmt(a.u60.y)],['Distance to reference · Δu′v′',fmt(a.deltaUV,6)]].map(([key,val])=>'<div><dt>'+esc(key)+'</dt><dd>'+esc(val)+'</dd></div>').join('');
 $('color-validity').textContent=k.valid?'CCT is within this calculator’s near-white domain. Positive Duv is above the Planckian locus; negative Duv is below it. Coordinates and purity remain relative color quantities.':k.bounded?'CCT is withheld because the closest radiator reaches the 1,000–100,000 K calculation limit. The reported Duv is a boundary-distance diagnostic; the source still has valid chromaticity coordinates.':'CCT is withheld because |Duv| exceeds 0.05. Saturated emitters can have valid chromaticity without a meaningful white-light color temperature.';
 $('color-white-description').textContent=descriptions[$('color-white').value];$('color-swatch').style.backgroundColor=a.preview.hex;$('color-preview-hex').textContent=a.preview.hex.toUpperCase();$('color-preview-note').textContent='Normalized sRGB preview'+(a.preview.clipped?' · out-of-gamut channels clipped':'');
 $('color-spectrum-output').hidden=!spectral;if(spectral)renderSpectrum();renderPlots();renderSaved();}
function csvCell(v){let s=String(v??'');if(typeof v==='string'&&/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function csv(rows,name){download(rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8',name);}
function parseData(text,label){let p;try{p=window.FTIRCore.parse(text);}catch(e){throw Error(e.message.replace('wavenumber (cm⁻¹) and signal','wavelength and intensity').replace('plot and detect bands','integrate the spectrum'));}p.label=label;parsed=p;for(const id of ['color-wave-column','color-power-column']){const select=$(id);select.innerHTML=p.headers.map((h,i)=>'<option value="'+i+'">'+esc(h)+'</option>').join('');select.disabled=false;}$('color-wave-column').value='0';$('color-power-column').value='1';status(label+': '+p.rows.length.toLocaleString()+' numeric rows read. Check columns, units and intensity basis, then calculate.');}
function integrate(){if(!parsed)throw Error('Upload or paste a numerical spectrum first.');const sp=C.spectrum(parsed.rows,{xcol:num('color-wave-column'),ycol:num('color-power-column'),unit:$('color-wave-unit').value,basis:$('color-basis').value,clamp:$('color-clamp').checked});setColor(sp.xy,parsed.label||'Emission spectrum',sp);status('Integrated '+fmt(sp.range[0],1)+'–'+fmt(sp.range[1],1)+' nm. '+sp.clipped+' negative values clipped; '+sp.duplicates+' duplicate wavelengths averaged; '+(sp.skipped+parsed.skipped)+' unusable rows skipped. Values outside the supplied interval are assumed zero.');}
function renderSpectrum(){const sp=spectral,pts=sp.points.filter(p=>p.w>=sp.range[0]&&p.w<=sp.range[1]),lo=sp.range[0],hi=sp.range[1],max=pts.reduce((m,p)=>Math.max(m,p.s),0),x=w=>65+(w-lo)/(hi-lo)*650,y=s=>230-s/(max||1)*190;let path='';for(let i=0;i<pts.length;i++){if(pts.length>3000&&i%Math.ceil(pts.length/3000)&&i!==pts.length-1)continue;path+=(path?'L':'M')+fmt(x(pts[i].w),2)+','+fmt(y(pts[i].s),2);}let ticks='';for(let i=0;i<=5;i++){const w=lo+(hi-lo)*i/5;ticks+='<line x1="'+x(w)+'" x2="'+x(w)+'" y1="230" y2="237" stroke="#698071"/><text x="'+x(w)+'" y="257" text-anchor="middle">'+fmt(w,0)+'</text>';}
 $('color-spectrum-chart').innerHTML='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 295" role="img" aria-label="Relative spectral radiant power against wavelength"><rect width="760" height="295" fill="#fffef9"/><g font-family="Arial,sans-serif" font-size="14" fill="#38583e"><path d="M65 35V230H715" fill="none" stroke="#698071"/>'+ticks+'<text x="390" y="285" text-anchor="middle">Wavelength / nm</text><text transform="translate(20,140) rotate(-90)" text-anchor="middle">Relative radiant power</text><text x="55" y="235" text-anchor="end">0</text><text x="55" y="45" text-anchor="end">1</text></g><path d="'+path+'" stroke="#365f4d" stroke-width="2.5" fill="none"/></svg>';
 $('color-spectrum-metrics').innerHTML=[['Sampled peak',fmt(sp.peak,1)+' nm'],['Apparent main-peak FWHM',sp.fwhm===null?'Unresolved / clipped':fmt(sp.fwhm,2)+' nm'],['Radiant-power centroid',fmt(sp.centroid,2)+' nm'],['Integrated-band luminous efficacy',fmt(sp.efficacy,2)+' lm/W']].map(([s,v])=>'<div><span>'+s+'</span><strong>'+v+'</strong></div>').join('');}
function renderSaved(){$('color-saved-body').innerHTML=saved.length?saved.map((s,i)=>{const a=C.analyze(s.p,white());return '<tr><td>'+esc((i+1)+'. '+s.name)+'</td><td>'+fmt(s.p.x)+'</td><td>'+fmt(s.p.y)+'</td><td>'+fmt(a.uv.x)+'</td><td>'+fmt(a.uv.y)+'</td><td>'+(a.cct.valid?Math.round(a.cct.temperature):'N/A')+'</td><td>'+signed(a.cct.duv)+'</td><td><button data-use-point="'+i+'">Use</button> <button data-remove-point="'+i+'" aria-label="Remove '+esc(s.name)+'">Remove</button></td></tr>';}).join(''):'<tr><td colspan="8">No saved points yet. Saved points stay in this tab until it is reloaded; download CSV to keep them.</td></tr>';}
function gamutValues(){return ['r','g','b'].map(k=>C.validateXY({x:num('gamut-'+k+'-x'),y:num('gamut-'+k+'-y')}));}
function calculateGamut(quiet=false){try{const d=gamutValues(),ref=C.spaces[$('gamut-reference').value],g=C.gamut(d,ref.rgb.map(([x,y])=>({x,y})));device=d;$('gamut-results').innerHTML=['xy','uv'].map(k=>'<tr><th>'+(k==='xy'?'CIE 1931 xy':'CIE 1976 u′v′')+'</th><td>'+fmt(g[k].deviceArea,6)+'</td><td>'+fmt(g[k].referenceArea,6)+'</td><td>'+fmt(g[k].ratio,2)+'%</td><td>'+fmt(g[k].coverage,2)+'%</td></tr>').join('');status('Compared with '+ref.name+'. Triangle area ratio and overlap coverage are reported separately.',false,'gamut-status');}catch(e){device=null;$('gamut-results').innerHTML='<tr><td colspan="5">Complete three valid, distinct primary colors to define the gamut.</td></tr>';if(!quiet)status(e.message,true,'gamut-status');}renderPlots();}
const configs={xy:{s:580,xmax:.8,ymax:.9,W:600,H:640},uv:{s:760,xmax:.65,ymax:.65,W:600,H:620}};
function tr(p,kind){return kind==='xy'?p:C.uv76(p);}
function background(kind){if(backgrounds[kind])return backgrounds[kind];const cfg=configs[kind],N=420,W=Math.round(N*cfg.xmax/cfg.ymax),H=N,poly=C.locus.map(p=>tr(p,kind)),canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;const ctx=canvas.getContext('2d'),im=ctx.createImageData(W,H);for(let j=0;j<H;j++){const y=cfg.ymax*(1-(j+.5)/H),cuts=[];for(let i=0,k=poly.length-1;i<poly.length;k=i++){const a=poly[i],b=poly[k];if((a.y>y)!==(b.y>y))cuts.push(a.x+(y-a.y)*(b.x-a.x)/(b.y-a.y));}cuts.sort((a,b)=>a-b);for(let k=0;k+1<cuts.length;k+=2){const first=Math.max(0,Math.ceil(cuts[k]/cfg.xmax*W-.5)),last=Math.min(W-1,Math.floor(cuts[k+1]/cfg.xmax*W-.5));for(let i=first;i<=last;i++){const x=(i+.5)*cfg.xmax/W,p=kind==='xy'?{x,y}:{x:9*x/(6*x-16*y+12),y:4*y/(6*x-16*y+12)},rgb=C.preview(p).rgb,o=(j*W+i)*4;im.data[o]=rgb[0];im.data[o+1]=rgb[1];im.data[o+2]=rgb[2];im.data[o+3]=255;}}}ctx.putImageData(im,0,0);return backgrounds[kind]=canvas.toDataURL('image/png');}
function plot(kind){const c=configs[kind],L=60,T=32,w=c.xmax*c.s,h=c.ymax*c.s,X=x=>L+x*c.s,Y=y=>T+h-y*c.s,pt=p=>{const q=tr(p,kind);return fmt(X(q.x),2)+','+fmt(Y(q.y),2);},path=points=>points.map((p,i)=>(i?'L':'M')+pt(p)).join('');
 let s='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+c.W+' '+c.H+'" role="img" aria-label="Interactive '+(kind==='xy'?'CIE 1931 xy':'CIE 1976 u prime v prime')+' chromaticity diagram"><title>CIE chromaticity diagram</title><desc>Official CIE 1931 2 degree observer, applicable to a 1 degree viewing field. CIE (2019), doi:10.25039/CIE.DS.xvudnb9b. Data and derived boundary licensed CC BY-SA 4.0.</desc><rect width="100%" height="100%" fill="#fffef9"/><image href="'+background(kind)+'" x="'+L+'" y="'+T+'" width="'+w+'" height="'+h+'"/><g font-family="Arial,sans-serif" font-size="14" fill="#244a36">';
 for(let t=0;t<=c.xmax+.001;t+=.1)s+='<path d="M'+X(t)+','+T+'V'+(T+h+5)+'" stroke="#3e5e4b" stroke-opacity=".16"/><text x="'+X(t)+'" y="'+(T+h+25)+'" text-anchor="middle">'+t.toFixed(1)+'</text>';
 for(let t=0;t<=c.ymax+.001;t+=.1)s+='<path d="M'+(L-5)+','+Y(t)+'H'+(L+w)+'" stroke="#3e5e4b" stroke-opacity=".16"/><text x="'+(L-11)+'" y="'+(Y(t)+5)+'" text-anchor="end">'+t.toFixed(1)+'</text>';
 s+='<path d="M'+L+','+T+'V'+(T+h)+'H'+(L+w)+'" stroke="#68806d" fill="none"/><text x="'+(L+w/2)+'" y="'+(T+h+50)+'" text-anchor="middle">'+(kind==='xy'?'x':'u′')+'</text><text x="20" y="'+(T+h/2)+'" text-anchor="middle">'+(kind==='xy'?'y':'v′')+'</text><path d="'+path(C.locus)+'Z" fill="none" stroke="#34553b" stroke-width="1.5"/>';
 for(const nm of [380,460,480,500,520,540,560,580,600,620,700]){const p=C.locus.find(q=>q.nm===nm);if(!p)continue;const q=tr(p,kind),offsets={380:[-8,22],460:[-21,7],480:[-22,4],500:[-21,0],520:[0,-10],540:[0,-10],560:[9,-9],580:[14,-7],600:[17,0],620:[15,4],700:[10,18]},o=offsets[nm];s+='<circle cx="'+X(q.x)+'" cy="'+Y(q.y)+'" r="2" fill="#284e35"/><text x="'+(X(q.x)+o[0])+'" y="'+(Y(q.y)+o[1])+'" text-anchor="middle" font-size="12" paint-order="stroke" stroke="#fffef9" stroke-width="3" stroke-linejoin="round">'+nm+'</text>';}
 if($('color-show-planck').checked){s+='<path d="'+path(C.planckSamples.map(q=>q.p))+'" fill="none" stroke="#202e2d" stroke-width="1.8"/>';for(const temp of [2000,6500,20000]){const p=C.temperatureXY(temp),q=tr(p,kind);s+='<text x="'+(X(q.x)+(temp===6500?(kind==='xy'?-50:20):5))+'" y="'+(Y(q.y)+(temp===6500?28:16))+'" font-size="11" paint-order="stroke" stroke="white" stroke-width="3">'+temp+' K</text>';}}
 const ref=C.spaces[$('gamut-reference').value].rgb.map(([x,y])=>({x,y}));s+='<path d="'+path(ref)+'Z" fill="none" stroke="#7851a2" stroke-width="2" stroke-dasharray="7 4"/>';
 if(device){s+='<path d="'+path(device)+'Z" fill="none" stroke="#0072a5" stroke-width="2.5"/>';device.forEach((p,i)=>{const q=tr(p,kind);s+='<text x="'+(X(q.x)+6)+'" y="'+(Y(q.y)-6)+'" font-weight="bold" paint-order="stroke" stroke="white" stroke-width="3">'+['R','G','B'][i]+'</text>';});}
 if($('color-show-purity').checked&&analysis.purity.boundary)s+='<path d="M'+pt(white())+'L'+pt(analysis.purity.boundary)+'" stroke="#252e35" stroke-width="1.5" stroke-dasharray="3 3" fill="none"/>';
 if($('color-show-whites').checked)for(const name of ['A','D50','D65','E']){const q=tr(C.whites[name],kind),o=(kind==='xy'?{A:[18,-20],D50:[-25,-20],D65:[-30,14],E:[32,10]}:{A:[20,-21],D50:[-35,-18],D65:[-35,7],E:[40,-3]})[name],xx=X(q.x),yy=Y(q.y);s+='<path d="M'+xx+','+yy+'L'+(xx+o[0])+','+(yy+o[1])+'" stroke="#526553" stroke-width=".65"/><circle cx="'+xx+'" cy="'+yy+'" r="2.6" fill="white" stroke="#354f44"><title>White point '+name+'</title></circle><text x="'+(xx+o[0])+'" y="'+(yy+o[1]-3)+'" text-anchor="middle" font-size="11" paint-order="stroke" stroke="white" stroke-width="3">'+name+'</text>';}
 const wp=tr(white(),kind);s+='<circle cx="'+X(wp.x)+'" cy="'+Y(wp.y)+'" r="5" fill="#f5d879" stroke="#554713" stroke-width="1.5"><title>Reference white W</title></circle><text x="'+(X(wp.x)+8)+'" y="'+(Y(wp.y)+19)+'" font-size="12" font-weight="bold" paint-order="stroke" stroke="white" stroke-width="3">W</text>';
 saved.forEach((p,i)=>{const q=tr(p.p,kind);s+='<circle cx="'+X(q.x)+'" cy="'+Y(q.y)+'" r="8" fill="white" stroke="#244b3b"/><text x="'+X(q.x)+'" y="'+(Y(q.y)+3)+'" text-anchor="middle" font-size="10">'+(i+1)+'</text>';});
 const q=tr(current,kind);s+='<circle cx="'+X(q.x)+'" cy="'+Y(q.y)+'" r="7" fill="none" stroke="white" stroke-width="5"/><circle cx="'+X(q.x)+'" cy="'+Y(q.y)+'" r="7" fill="none" stroke="#172c28" stroke-width="2"/><path d="M'+(X(q.x)-12)+','+Y(q.y)+'H'+(X(q.x)+12)+'M'+X(q.x)+','+(Y(q.y)-12)+'V'+(Y(q.y)+12)+'" stroke="#172c28" stroke-width="1.4"/>';
 s+='<text x="'+L+'" y="'+(c.H-17)+'" font-size="10" fill="#647760">CIE (2019) · 1 nm CMFs · doi:10.25039/CIE.DS.xvudnb9b · CC BY-SA 4.0</text></g></svg>';return s;}
function renderPlots(){for(const k of ['xy','uv'])$('cie-'+k+'-plot').innerHTML=plot(k);}
document.addEventListener('cie-load-spectrum',e=>{try{mode('spectrum');parseData(e.detail.text,e.detail.name);$('color-wave-unit').value='nm';$('color-basis').value='power';integrate();status(e.detail.name+' loaded as a reference example.');}catch(error){status(error.message,true);}});
// Bindings
 document.querySelectorAll('[data-color-mode]').forEach(b=>b.addEventListener('click',()=>mode(b.dataset.colorMode)));
 $('color-coordinate-kind').addEventListener('change',syncCoordinates);
 $('color-calculate').addEventListener('click',guard(()=>{const kind=$('color-coordinate-kind').value,a=num('color-a'),b=num('color-b');setColor(kind==='xy'?{x:a,y:b}:kind==='uv'?C.uvXY(a,b):C.xyzXY({X:a,Y:b,Z:num('color-c')}),'Coordinate input');}));
 $('color-from-temperature').addEventListener('click',guard(()=>setColor(C.temperatureXY(num('color-temperature'),num('color-input-duv')),'CCT + Duv input')));
 $('color-file').addEventListener('change',async()=>{try{const f=$('color-file').files[0];if(!f)return;if(f.size>8e6)throw Error('Use a text spectrum smaller than 8 MB.');parseData(await f.text(),f.name);}catch(e){status(e.message,true);}});
 $('color-read-paste').addEventListener('click',guard(()=>parseData($('color-spectrum-text').value,'Pasted spectrum')));
 $('color-integrate').addEventListener('click',guard(integrate));
 $('color-load-example').addEventListener('click',guard(()=>{const kind=$('color-example-kind').value,wave={blue:[465,8],green:[530,10],red:[630,10]}[kind];const rows=Array.from({length:471},(_,i)=>{const w=i+360;return [w,kind==='white'?(560/w)**5/Math.expm1(.014387768775/(w*1e-9*6500)):Math.exp(-.5*((w-wave[0])/wave[1])**2)];});$('color-spectrum-text').value='Wavelength_nm,Relative_power\n'+rows.map(r=>r.join(',')).join('\n');parseData($('color-spectrum-text').value,'Illustrative '+kind+' spectrum');$('color-wave-unit').value='nm';$('color-basis').value='power';integrate();status('Illustrative '+kind+' spectrum calculated. Synthetic example, not a measured research result.');}));
 $('color-white').addEventListener('change',guard(()=>{$('color-custom-white').hidden=$('color-white').value!=='custom';render();}));for(const id of ['color-white-x','color-white-y'])$(id).addEventListener('change',guard(render));
 $('color-use-white').addEventListener('click',guard(()=>{mode('coordinates');setColor(white(),'Reference white '+$('color-white').value);}));
 for(const id of ['color-show-planck','color-show-whites','color-show-purity'])$(id).addEventListener('change',guard(renderPlots));
 for(const kind of ['xy','uv'])$('cie-'+kind+'-plot').addEventListener('click',e=>{try{const svg=e.currentTarget.querySelector('svg'),p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(svg.getScreenCTM().inverse()),c=configs[kind],x=(q.x-60)/c.s,y=(32+c.ymax*c.s-q.y)/c.s;const xy=kind==='xy'?C.validateXY({x,y}):C.uvXY(x,y);mode('coordinates');setColor(xy,'Diagram selection');}catch(err){status('Choose a point inside the colored spectral boundary.',true);}});
 document.querySelectorAll('[data-export-diagram]').forEach(b=>b.addEventListener('click',()=>download($('cie-'+b.dataset.exportDiagram+'-plot').innerHTML,'image/svg+xml','CIE-'+(b.dataset.exportDiagram==='xy'?'1931-xy':'1976-uv')+'.svg')));
 $('color-save-point').addEventListener('click',guard(()=>{if(saved.length>=20)throw Error('Save up to 20 points per tab. Download or remove points to continue.');saved.push({p:{...current},name:$('color-point-name').value.trim()||'Sample '+(saved.length+1),source});$('color-point-name').value='Sample '+(saved.length+1);renderSaved();renderPlots();status('Point saved in this tab. Download CSV to keep your points.');}));
 $('color-saved-body').addEventListener('click',e=>{const use=e.target.closest('[data-use-point]'),remove=e.target.closest('[data-remove-point]');if(use){const s=saved[Number(use.dataset.usePoint)];setColor(s.p,s.name);mode('coordinates');}if(remove){saved.splice(Number(remove.dataset.removePoint),1);renderSaved();renderPlots();}});
 $('color-clear-points').addEventListener('click',()=>{saved=[];renderSaved();renderPlots();});
 $('color-export-points').addEventListener('click',guard(()=>{if(!saved.length)throw Error('Save at least one point first.');csv([['Label','x','y','u_prime','v_prime','CCT_K','Duv_1960','Source'],...saved.map(s=>{const a=C.analyze(s.p,white());return[s.name,s.p.x,s.p.y,a.uv.x,a.uv.y,a.cct.valid?a.cct.temperature:'N/A',a.cct.duv,s.source];})],'CIE-saved-points.csv');}));
 $('color-export-result').addEventListener('click',guard(()=>{const a=analysis,p=a.purity;const rows=[['Parameter','Value','Unit / scope'],['Observer','CIE 1931 2 degree','Applicable to 1 degree field'],['Source',source,''],['x',current.x,''],['y',current.y,''],['z',1-current.x-current.y,''],['X',a.xyz.X,'relative Y=100'],['Y',100,'relative'],['Z',a.xyz.Z,'relative Y=100'],['u_prime',a.uv.x,'CIE 1976'],['v_prime',a.uv.y,'CIE 1976'],['CCT',a.cct.valid?a.cct.temperature:'N/A','K; 1000–100000; |Duv| <=0.05'],['Duv',a.cct.duv,'CIE 1960 uv; diagnostic when CCT N/A'],['Reference white',$('color-white').value,''],['Reference x',white().x,''],['Reference y',white().y,''],['Excitation purity',p.purity,'%'],[p.kind,p.wavelength??'Undefined','nm'],['Delta uprime vprime',a.deltaUV,'distance to selected white']];if(spectral)rows.push(['Peak',spectral.peak,'nm'],['FWHM',spectral.fwhm??'Unresolved','nm'],['Centroid',spectral.centroid,'nm'],['Integrated band efficacy',spectral.efficacy,'lm/W radiant power within supplied visible interval'],['Integration minimum',spectral.range[0],'nm'],['Integration maximum',spectral.range[1],'nm']);csv(rows,'CIE-current-result.csv');}));
 $('gamut-calculate').addEventListener('click',()=>calculateGamut());$('gamut-reference').addEventListener('change',()=>{if(device)calculateGamut();else renderPlots();});
 $('gamut-load-example').addEventListener('click',()=>{C.spaces[$('gamut-example').value].rgb.forEach(([x,y],i)=>{const k=['r','g','b'][i];$('gamut-'+k+'-x').value=x;$('gamut-'+k+'-y').value=y;});calculateGamut();status('Illustrative preset loaded: '+C.spaces[$('gamut-example').value].name+'.',false,'gamut-status');});
 document.querySelectorAll('[data-assign-primary]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.assignPrimary;$('gamut-'+k+'-x').value=fmt(current.x,8);$('gamut-'+k+'-y').value=fmt(current.y,8);calculateGamut(true);status('Current color assigned as '+k.toUpperCase()+'. Complete all RGB primaries to calculate the gamut.',false,'gamut-status');}));
 for(const k of ['r','g','b'])for(const axis of ['x','y'])$('gamut-'+k+'-'+axis).addEventListener('input',()=>{device=null;$('gamut-results').innerHTML='<tr><td colspan="5">Inputs changed. Calculate again to update the gamut.</td></tr>';renderPlots();});
 $('color-whites-body').innerHTML=Object.entries(C.whites).map(([name,p])=>{const q=C.uv76(p);return '<tr><th>'+name+'</th><td>'+fmt(p.x)+'</td><td>'+fmt(p.y)+'</td><td>'+fmt(q.x)+'</td><td>'+fmt(q.y)+'</td><td><button data-white-input="'+name+'">Use '+name+'</button></td></tr>';}).join('');
 $('color-whites-body').addEventListener('click',e=>{const b=e.target.closest('[data-white-input]');if(b){mode('coordinates');setColor(C.whites[b.dataset.whiteInput],'White point '+b.dataset.whiteInput);$('color-inputs').scrollIntoView({behavior:'smooth'});}});
 render();
})();
